'use strict';
const SOLO_SKIP_LIMIT=3;
const slots=['PG','SG','SF','PF','C'];
const pools=window.HBW_BASKETBALL_DATA.pools;
let selectedMode='current';
const modeNames={current:'Current Players',prime:'All-Time Players'};
function playerPool(){return pools[selectedMode];}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function makeDeck(){return shuffle(playerPool());}
// Every eligible basketball player has exactly the same draw probability.
function drawPlayer(available){return available[Math.floor(Math.random()*available.length)];}
function fitScore(p,slot){const natural=p.positions||[p.pos];const distance=Math.min(...natural.map(pos=>Math.abs(slots.indexOf(pos)-slots.indexOf(slot))));return Math.round(p.rating*[1,.92,.80,.62,.45][distance]);}
// At most 120 assignments. All five positions are always considered.
function bestLineup(squad){let best={total:-1,rows:Array(5).fill(null)};function visit(index,rows,total){if(index===squad.length){if(total>best.total)best={total,rows:[...rows]};return;}const signing=squad[index];for(let i=0;i<5;i++){if(rows[i])continue;rows[i]={...signing,slot:slots[i],score:fitScore(signing.player,slots[i])};visit(index+1,rows,total+rows[i].score);rows[i]=null;}}visit(0,Array(5).fill(null),0);best.rating=best.total/5;return best;}

// The suggested arrangement is a starting point. A manager's swaps decide the final score.
function lineupFor(team){
 const ids=team.order;
 if(!Array.isArray(ids)||ids.length!==5)return bestLineup(team.squad);
 const signings=new Map(team.squad.map(s=>[s.player.id,s]));
 const used=new Set();let total=0;
 const rows=ids.map((id,i)=>{const signing=signings.get(id);if(id==null||!signing||used.has(id))return null;used.add(id);const score=fitScore(signing.player,slots[i]);total+=score;return {...signing,slot:slots[i],score};});
 if(used.size!==team.squad.length)return bestLineup(team.squad);
 return {rows,total,rating:total/5};
}
function syncLineup(team){
 if(!team.customized){team.order=bestLineup(team.squad).rows.map(r=>r?.player.id??null);return;}
 if(!Array.isArray(team.order))team.order=Array(5).fill(null);
 const used=new Set(team.order.filter(id=>id!=null));
 for(const signing of team.squad){if(used.has(signing.player.id))continue;const open=team.order.map((id,i)=>id==null?i:-1).filter(i=>i>=0);const target=open.reduce((best,i)=>fitScore(signing.player,slots[i])>fitScore(signing.player,slots[best])?i:best,open[0]);team.order[target]=signing.player.id;used.add(signing.player.id);}
}
function canArrange(t){return !state.revealing&&!state.revealed&&state.teams[t].squad.length>0&&(['bidding','sold','unsold','free-ready'].includes(state.phase)||(state.phase==='lineup'&&!state.teams[t].ready));}
let selectedSlot=null,dragState=null,dragPlaceholder=null,dropRow=null,suppressRowClick=false;
function movePlayer(t,from,to){
 if(!Number.isInteger(t)||![0,1].includes(t)||!Number.isInteger(from)||!Number.isInteger(to)||from<0||from>4||to<0||to>4||!canArrange(t))throw Error('This lineup cannot be changed now.');
 if(from===to)return readState();
 const team=state.teams[t];if(!Array.isArray(team.order))syncLineup(team);
 if(team.order[from]==null)throw Error('Select a signed player to move.');
 const moved=team.squad.find(s=>s.player.id===team.order[from]);
 [team.order[from],team.order[to]]=[team.order[to],team.order[from]];team.customized=true;selectedSlot=null;
 state.message=`Player ${t+1} moves ${moved.player.name} to ${slots[to]}.`;render();window.HBW_SOUND?.move();
 const target=document.querySelector?.(`#team-${t} .roster-row[data-slot="${to}"]`);
 if(target?.animate&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)target.animate([{transform:'translateY(-9px) scale(1.05)',filter:'brightness(1.6)'},{transform:'translateY(0) scale(1)',filter:'brightness(1)'}],{duration:460,easing:'cubic-bezier(.18,.9,.2,1)'});
 return readState();
}
function readyLineup(t){
 if(state.phase!=='lineup'||![0,1].includes(t))throw Error('Final lineup changes are not open.');
 state.teams[t].ready=!state.teams[t].ready;selectedSlot=null;window.HBW_SOUND?.lock();
 if(state.teams.every(team=>team.ready)){state.phase='done';state.message='Both managers are locked in. The final verdict is coming!';render();showResults();}
 else{state.message=`Player ${t+1} ${state.teams[t].ready?'locked in':'is editing again'}. Both managers must be ready.`;render();}
 return readState();
}

let lastCardKey=null;
let state,spinTimer,spinInterval,spinResolve,epoch=0,tossTimer,tossResolve;
const $=id=>document.getElementById(id);
let revealTimers=[];
function reset(mode=selectedMode){revealTimers.forEach(clearTimeout);revealTimers=[];selectedSlot=null;clearDrag();if(!['current','prime'].includes(mode))throw Error('Unknown game mode.');selectedMode=mode;epoch++;clearTimeout(tossTimer);if(tossResolve){tossResolve({cancelled:true});tossResolve=null;}clearTimeout(spinTimer);clearInterval(spinInterval);if(spinResolve){spinResolve({cancelled:true});spinResolve=null;}state={teams:[{money:20,squad:[],soloSkips:0,order:Array(5).fill(null),customized:false,ready:false},{money:20,squad:[],soloSkips:0,order:Array(5).fill(null),customized:false,ready:false}],mode:selectedMode,deck:makeDeck(),revealed:false,revealing:false,phase:'toss-ready',firstBidder:null,lot:0,current:null,bid:0,leader:null,turn:0,passed:[false,false],message:'A 50/50 toss decides who opens the first auction.'};$('results').hidden=true;$('results').innerHTML='';render();}
function maxBid(t){const team=state.teams[t];return team.squad.length===5?0:team.money;}
function active(t){return state.teams[t].squad.length<5&&state.teams[t].money>0&&!state.passed[t];}
function soloAuction(t){const opponent=state.teams[1-t];return state.bid===0&&(opponent.money===0||opponent.squad.length===5);}
function soloSkipsLeft(t){return SOLO_SKIP_LIMIT-state.teams[t].soloSkips;}
function canPass(t){return !soloAuction(t)||soloSkipsLeft(t)>0;}
function card(p,spinning=false){const type=p.kind==='Season'?'CURRENT PLAYER':p.kind==='Legend'?'LEGEND':'ALL-TIME PLAYER';return `<div class="player-card identity-card ${p.kind==='Legend'?'legend-card':''} ${spinning?'spinning':'revealed'}"><div class="card-top"><span class="card-position">${p.positions.join(' / ')}</span></div><div class="player-monogram" aria-hidden="true">${p.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</div><div class="card-name">${p.name}</div><div class="card-meta">${type}</div></div>`;}
function spotlight(){if(state.phase==='bidding')return state.turn;if(['free-ready','free-spinning'].includes(state.phase))return state.freeTurn;if(state.phase==='ready'&&state.lot===0)return state.firstBidder;return null;}
function renderTeams(){if(dragState)clearDrag();if(selectedSlot&&!canArrange(selectedSlot.team))selectedSlot=null;for(let t=0;t<2;t++){
 const team=state.teams[t],lineup=lineupFor(team),editable=canArrange(t),picked=selectedSlot?.team===t?selectedSlot.slot:null;
 const panel=$('team-'+t);panel.classList.toggle('active-turn',spotlight()===t);panel.classList.toggle('lineup-ready',!!team.ready);panel.classList.toggle('can-arrange',editable);
 panel.setAttribute('aria-label',`Player ${t+1}${spotlight()===t?' — active player':''}${team.ready?' — lineup locked':''}`);
 panel.innerHTML=`<div class="team-head"><div class="manager-number">0${t+1}</div><div class="team-title"><h2>PLAYER ${t+1}</h2><small>${t?'The challenger':'The home side'}</small></div><span class="team-tag">${team.ready?'LOCKED IN':state.phase==='lineup'?'FINAL EDIT':team.squad.length===5?'FULL SQUAD':spotlight()===t?(state.phase==='bidding'?'YOUR BID':'YOUR TURN'):team.money===0?'WAITING':'READY'}</span></div><div class="budget-area"><div><div class="tiny-label">BUDGET LEFT</div><div class="budget">$${team.money}<small>/ $20</small></div></div></div><div class="roster-heading"><span>${['lineup','done'].includes(state.phase)?'FINAL LINEUP':'YOUR STARTING FIVE'}</span><span>${editable?'DRAG TO MOVE':`${team.squad.length} / 5`}</span></div><div class="roster">${lineup.rows.map((r,i)=>`<div class="roster-row ${r?'':'empty'} ${editable?'repositionable':''} ${picked===i?'selected-slot':''}" data-team="${t}" data-slot="${i}" ${editable?`role="button" tabindex="0" aria-label="${r?`${r.player.name} in ${slots[i]}. Select and choose another slot`:`Empty ${slots[i]} slot. Select to move a player here`}"`:''}><span class="slot-label">${slots[i]}</span><span class="roster-name">${r?`${r.player.name}<small>${r.price===0?'FREE PICK':'$'+r.price} · ${r.player.pos}${!(r.player.positions||[r.player.pos]).includes(slots[i])?` → ${slots[i]}${state.revealed?` · −${r.player.rating-r.score}`:''}`:''}</small>`:'Open position'}</span>${state.revealed&&r?`<span class="roster-score ${!(r.player.positions||[r.player.pos]).includes(slots[i])?'penalty':''}">${r.score}</span>`:r&&editable?'<span class="move-hint" aria-hidden="true">↕</span>':r?'':'<span>+</span>'}</div>`).join('')}</div><div class="team-total">${state.revealed?`<span>TEAM RATING</span><strong>${lineup.rating.toFixed(1)}</strong>`:`<span class="rating-sealed">${team.ready?'✓ LINEUP LOCKED':'✦ RATING SEALED'}</span>`}</div>`;
}}

function render(){if(!state.current)lastCardKey=null;renderTeams();const signed=state.teams.reduce((n,t)=>n+t.squad.length,0);$('progress').innerHTML=Array.from({length:10},(_,i)=>`<span class="${i<signed?'filled':''}"></span>`).join('');$('progress').setAttribute('aria-label',`${signed} of 10 players signed`);$('signed-count').textContent=`${signed} / 10 SIGNED`;$('phase-title').textContent=state.phase==='done'?'The final whistle':state.phase==='lineup'?'Final tactics':state.phase==='final-signing'?'Last signing':'Build your five';$('lot').textContent=state.lot?`AUCTION ${String(state.lot).padStart(2,'0')}`:'AUCTION FLOOR';$('stage').textContent=({'toss-ready':'WHO GOES FIRST?',tossing:'FLIPPING…',ready:'READY TO SPIN',spinning:'SCOUTING…',bidding:'BIDDING OPEN',sold:'DEAL DONE',unsold:'UNSOLD','free-ready':'FREE PICK ROUND','free-spinning':'REVEALING FREE PICK…','final-signing':'LAST SIGNING',lineup:'FINAL LINEUPS',done:'SQUADS COMPLETE'})[state.phase];$('announcement').textContent=state.message;document.querySelector('.auction').setAttribute('data-player',spotlight()===null?'':String(spotlight()+1));document.querySelector('.auction').setAttribute('data-phase',state.phase);
if(state.phase==='lineup'||state.phase==='done'){$('card-zone').innerHTML=`<div class="lineup-stage"><div class="lineup-stage-kicker">${state.phase==='done'?'LOCKED IN':'THE FINAL CHECK'}</div><div class="lineup-stage-mark">5<span>↔</span>5</div><h2>${state.phase==='done'?'FINAL<br><em>WHISTLE.</em>':'MAKE YOUR<br><em>FINAL MOVE.</em>'}</h2><p>${state.phase==='done'?'Both lineups are set.':'Drag a player to move or swap. Or tap a player, then a slot.'}</p><div class="lineup-stage-status"><span class="${state.teams[0].ready?'locked':''}">P1 ${state.teams[0].ready?'✓':'○'}</span><span class="${state.teams[1].ready?'locked':''}">P2 ${state.teams[1].ready?'✓':'○'}</span></div></div>`;}else if(state.phase==='toss-ready'||state.phase==='tossing'){$('card-zone').innerHTML=`<div class="toss-area"><div class="toss-coin ${state.phase==='tossing'?'flipping':''}"><span>1</span><i>/</i><span>2</span></div><h2>Who bids first?</h2><p></p></div>`;}else if(state.phase==='ready'&&state.lot===0){$('card-zone').innerHTML=`<div class="toss-area toss-winner p${state.firstBidder+1}"><div class="toss-coin">${state.firstBidder+1}</div><h2>PLAYER ${state.firstBidder+1} WINS!</h2><p>You have the first bid.</p></div>`;}else if(state.current){const spinning=['spinning','free-spinning'].includes(state.phase),key=state.current.id+':'+spinning;if(key!==lastCardKey){$('card-zone').innerHTML=card(state.current,spinning);lastCardKey=key;}}else{$('card-zone').innerHTML=`<div class="player-card mystery"><div class="question">?</div><div class="card-name">YOUR NEXT SIGNING</div><div class="card-meta">${selectedMode==='prime'?'STARS · CULT HEROES':'STARS · FAN FAVOURITES'}</div></div>`;}
if(['toss-ready','tossing'].includes(state.phase)){$('auction-controls').innerHTML=`<button class="primary" id="toss" ${state.phase==='tossing'?'disabled':''}>${state.phase==='tossing'?'Flipping the coin…':'Toss for first bid ↻'}</button><p class="control-hint">The opening turn alternates after each auction.</p>`;$('toss').onclick=toss;}else if(state.phase==='bidding'){const allowed=maxBid(state.turn)>=state.bid+1,solo=soloAuction(state.turn),skips=soloSkipsLeft(state.turn);$('auction-controls').innerHTML=`<div class="bid-top"><div><small>${state.bid?'CURRENT BID':'OPENING BID'}</small><strong>$${state.bid||1}</strong></div><div class="turn-label p${state.turn+1}"><b>Player ${state.turn+1}’s turn</b><small>${state.leader===null?'Be the first to bid':`Player ${state.leader+1} is leading`}</small></div></div><div class="bid-buttons"><button class="primary" id="bid" ${allowed?'':'disabled'}>${state.bid?`Raise to $${state.bid+1}`:solo?'Sign for $1':'Open at $1'} ↑</button><button class="quiet" id="pass" ${canPass(state.turn)?'':'disabled'}>${solo?`Skip (${skips})`:'Pass'}</button></div><button class="all-in text-button" id="all-in" ${allowed?'':'disabled'}>All in · $${maxBid(state.turn)}</button><p class="control-hint">${solo?`${skips} solo skips left. ${skips?'Skip or sign for $1.':'You must sign this player.'}`:allowed?`Bid up to $${maxBid(state.turn)}.`:'Your maximum bid is reached. Pass to finish this auction.'}</p>`;$('bid').onclick=()=>bid(state.turn);$('pass').onclick=()=>pass(state.turn);if($('all-in'))$('all-in').onclick=()=>bid(state.turn,maxBid(state.turn));
}else if(['free-ready','free-spinning'].includes(state.phase)){$('auction-controls').innerHTML=`<div class="free-turn">PLAYER ${state.freeTurn+1} · FREE PICK ${state.teams[state.freeTurn].squad.length+1} / 5</div><button class="primary" id="spin" ${state.phase==='free-spinning'?'disabled':''}>${state.phase==='free-spinning'?'Revealing your free signing…':'Spin one free signing ↻'}</button><p class="control-hint">This random signing is yours. No bidding or skipping.</p>`;$('spin').onclick=spin;}else if(state.phase==='final-signing'){$('auction-controls').innerHTML='<button class=\"primary\" id=\"final-lineups\">Set final lineups <span class=\"arrow\">→</span></button><p class=\"control-hint\">Take a look at the last signing before you move on.</p>';$('final-lineups').onclick=advanceToLineup;}else if(state.phase==='lineup'){$('auction-controls').innerHTML=`<div class="lineup-ready-actions"><button class="primary ${state.teams[0].ready?'is-ready':''}" id="ready-0">${state.teams[0].ready?'✓ Player 1 locked · Edit':'Player 1 · Lock in'}</button><button class="primary ${state.teams[1].ready?'is-ready':''}" id="ready-1">${state.teams[1].ready?'✓ Player 2 locked · Edit':'Player 2 · Lock in'}</button></div><p class="control-hint">The winner is revealed when both players lock in.</p>`;$('ready-0').onclick=()=>readyLineup(0);$('ready-1').onclick=()=>readyLineup(1);
}else if(state.phase==='done'){$('auction-controls').innerHTML='<button class="primary" id="show-results">Reveal the winner <span class="arrow">✦</span></button>';$('show-results').onclick=()=>showResults();
}else{$('auction-controls').innerHTML=`<button class="primary" id="spin" ${state.phase==='spinning'?'disabled':''}>${state.phase==='spinning'?'Finding your next signing…':state.lot?'Spin the next basketball player':'Spin a basketball player'} <span class="arrow">↻</span></button><p class="control-hint">${state.lot?'Choose carefully. Five signings are final.':'Reveal first. Then let the bidding begin.'}</p>`;$('spin').onclick=spin;}}
function playCue(kind,t){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const target=kind==='bid'?document.querySelector('.bid-top strong'):$('team-'+t);target?.animate?.(kind==='bid'?[{transform:'scale(.72)',opacity:.45},{transform:'scale(1.16)',opacity:1},{transform:'scale(1)',opacity:1}]:[{transform:'scale(.98)',filter:'brightness(1.4)'},{transform:'scale(1)',filter:'brightness(1)'}],{duration:kind==='bid'?360:520,easing:'cubic-bezier(.2,.8,.2,1)'});}
function toss(){if(state.phase!=='toss-ready'||!$('home').hidden)throw Error('Start a game before tossing.');state.phase='tossing';state.firstBidder=Math.random()<.5?0:1;state.message='Heads for Player 1. Tails for Player 2.';render();window.HBW_SOUND?.toss();const run=epoch;return new Promise(resolve=>{tossResolve=resolve;tossTimer=setTimeout(()=>{tossResolve=null;if(run!==epoch){resolve({cancelled:true});return;}state.phase='ready';state.message=`Player ${state.firstBidder+1} won the toss and bids first. Spin to reveal the basketball player.`;render();window.HBW_SOUND?.start();resolve(readState());},window.matchMedia('(prefers-reduced-motion: reduce)').matches?80:1600);});}
function spin(){if(!$('home').hidden)throw Error('Choose a mode and start a game first.');if(state.phase==='free-ready')return spinFree();if(!['ready','sold','unsold'].includes(state.phase))throw Error('Finish the current auction first.');if(!state.deck.length){const signed=new Set(state.teams.flatMap(t=>t.squad.map(s=>s.player.id)));state.deck=shuffle(playerPool().filter(p=>!signed.has(p.id)));}const chosen=drawPlayer(state.deck);state.deck=state.deck.filter(p=>p.id!==chosen.id);state.phase='spinning';state.current=chosen;state.lot++;state.bid=0;state.leader=null;state.passed=[false,false];state.message='Scouting the stars. Who’s coming out next?';render();window.HBW_SOUND?.tick(0);const run=epoch,reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;return new Promise(resolve=>{spinResolve=resolve;if(!reduced){let frames=0;spinInterval=setInterval(()=>{$('card-zone').innerHTML=card(playerPool()[Math.floor(Math.random()*playerPool().length)],true);if(++frames%2===0&&frames<17)window.HBW_SOUND?.tick(frames/18)},100);}spinTimer=setTimeout(()=>{clearInterval(spinInterval);spinResolve=null;if(run!==epoch){resolve({cancelled:true});return;}state.phase='bidding';state.turn=(state.firstBidder+state.lot-1)%2;if(!active(state.turn))state.turn=1-state.turn;state.message=`${chosen.name} is up for bid.`;render();window.HBW_SOUND?.settle();resolve(readState());},reduced?100:1800);});}
function assertTurn(t){if(state.phase!=='bidding'||!Number.isInteger(t)||t!==state.turn||!active(t))throw Error('It is not this player’s bidding turn.');}
function bid(t,amount=state.bid+1){assertTurn(t);if(!Number.isInteger(amount)||amount<=state.bid)throw Error('Bid must be a whole dollar above the current bid.');if(amount>maxBid(t))throw Error('Bid exceeds your available budget.');state.bid=amount;state.leader=t;const opponent=1-t;if(!active(opponent)){award();return readState();}state.turn=opponent;state.message=`Player ${t+1} bids $${amount} for ${state.current.name}.`;render();playCue('bid',t);window.HBW_SOUND?.bid();return readState();}
function pass(t){assertTurn(t);if(!canPass(t))throw Error('No solo skips left. Sign this basketball player for $1 or more.');const solo=soloAuction(t);if(solo)state.teams[t].soloSkips++;state.passed[t]=true;if(state.leader!==null){award();return readState();}const other=1-t;if(active(other)){state.turn=other;state.message=`Player ${t+1} passes. Player ${other+1}, open at $1 or pass.`;}else{state.phase='unsold';state.message=`No bids for ${state.current.name}. Spin again for a new basketball player.${solo?` ${soloSkipsLeft(t)} solo skips left for this match.`:''}`;}render();window.HBW_SOUND?.pass();return readState();}
function advanceToLineup(){if(state.phase!=='final-signing')throw Error('Review the last signing first.');state.phase='lineup';state.message='Make final changes, then both managers lock in.';render();return readState();}
function nextPhase(){if(state.teams.every(t=>t.squad.length===5)){state.phase='final-signing';state.teams.forEach(team=>team.ready=false);return;}if(state.teams.some(t=>t.money>0&&t.squad.length<5)){state.phase='sold';return;}state.phase='free-ready';state.freeTurn=state.teams.findIndex(t=>t.squad.length<5);}
function award(){const t=state.leader;state.teams[t].money-=state.bid;state.teams[t].squad.push({player:state.current,price:state.bid});syncLineup(state.teams[t]);nextPhase();state.message=`SOLD! ${state.current.name} joins Player ${t+1} for $${state.bid}.`+(state.teams[t].money===0&&state.teams[t].squad.length<5?' Budget spent; free picks come after paid bidding.':'');if(state.phase==='final-signing')state.message+=' The last signing is yours to review before final lineups.';if(state.phase==='free-ready')state.message=`SOLD! ${state.current.name} for $${state.bid}. Paid bidding is over — spin your free picks.`;render();playCue('sign',t);window.HBW_SOUND?.sign();}
function spinFree(){const t=state.freeTurn;const claimed=new Set(state.teams.flatMap(t=>t.squad.map(s=>s.player.id)));const available=playerPool().filter(p=>!claimed.has(p.id));const chosen=drawPlayer(available);state.phase='free-spinning';state.current=chosen;state.message=`Player ${t+1}, this next free signing is yours.`;render();window.HBW_SOUND?.tick(0);const run=epoch,reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;return new Promise(resolve=>{spinResolve=resolve;if(!reduced){let frames=0;spinInterval=setInterval(()=>{$('card-zone').innerHTML=card(available[Math.floor(Math.random()*available.length)],true);if(++frames%2===0&&frames<17)window.HBW_SOUND?.tick(frames/18)},100);}spinTimer=setTimeout(()=>{clearInterval(spinInterval);spinResolve=null;if(run!==epoch){resolve({cancelled:true});return;}state.teams[t].squad.push({player:chosen,price:0});syncLineup(state.teams[t]);state.deck=state.deck.filter(p=>p.id!==chosen.id);nextPhase();state.message=`FREE SIGNING! ${chosen.name} joins Player ${t+1}.`+(state.phase==='free-ready'?` Player ${state.freeTurn+1}, spin your next free pick.`:' Last signing complete. Review the card, then set final lineups.');render();window.HBW_SOUND?.sign();playCue('sign',t);resolve(readState());},reduced?100:1800);});}
function showResults(scroll=true){
 if(state.phase!=='done')throw Error(state.phase==='lineup'?'Both managers must lock in their final lineups.':'Both squads need five players.');
 const scores=state.teams.map(lineupFor);
 const winner=scores[0].total===scores[1].total?null:scores[0].total>scores[1].total?0:1;
 const result={winner:winner===null?'draw':`Player ${winner+1}`,ratings:scores.map(s=>s.rating)};
 if(state.revealing||state.revealed){if(scroll)$('results').scrollIntoView({behavior:'smooth',block:'center'});return result;}
 state.revealing=true;
 const run=epoch,reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const finish=()=>{
  if(run!==epoch||!state.revealing)return;
  revealTimers.forEach(clearTimeout);revealTimers=[];state.revealing=false;state.revealed=true;
  const gap=(Math.abs(scores[0].total-scores[1].total)/5).toFixed(1);
  const color=winner===null?'var(--lime)':winner===0?'var(--blue)':'var(--orange)';
  $('results').innerHTML=`<div class="result-panel finale finished" style="--winner-color:${color}">
   <div class="confetti" aria-hidden="true">${Array.from({length:32},(_,i)=>`<i style="--x:${(i*37)%100}%;--delay:${(i%7)*.09}s;--drift:${(i%2?1:-1)*(25+i%5*20)}px;--spin:${i*47}deg"></i>`).join('')}</div>
   <div class="eyebrow">THE FINAL VERDICT</div><h2 tabindex="-1" id="winner-heading">${winner===null?'DEAD EVEN.':`PLAYER ${winner+1} WINS!`}</h2>
   <p class="result-note">${winner===null?'Same score. Shared bragging rights.':Number(gap)<1?`A photo finish. Just ${gap} points in it.`:`${gap} points clear. Bragging rights secured.`}</p>
   <div class="result-scores">${scores.map((score,i)=>`${i?'<span class="final-vs">VS</span>':''}<div class="final-score ${winner===i?'champion':''}" style="--team-color:${i?'var(--orange)':'var(--blue)'}"><div class="tiny-label">PLAYER ${i+1}</div><strong>${score.rating.toFixed(1)}</strong><small>Adjusted team rating</small><span class="winner-badge">${winner===null?'DRAW':winner===i?'WINNER':'RUNNER-UP'}</span></div>`).join('')}</div>
   <button class="primary" id="rematch">Run it back ↻</button><button class="text-button" id="view-lineups">See final lineups ↑</button></div>`;
  renderTeams();
  window.HBW_SOUND?.[winner===null?'draw':'win']();
  $('announcement').textContent=winner===null?'The final scores are tied.':`Player ${winner+1} wins the showdown!`;
  $('show-results').textContent='View final scores ✦';
  $('rematch').onclick=()=>{window.HBW_SOUND?.start();reset();window.scrollTo({top:0,behavior:'smooth'});};
  $('view-lineups').onclick=()=>$('team-0').scrollIntoView({behavior:reduced?'auto':'smooth',block:'center'});
  if(scroll){$('results').scrollIntoView({behavior:reduced?'auto':'smooth',block:'center'});$('winner-heading').focus?.({preventScroll:true});}
 };
 $('results').hidden=false;
 $('results').innerHTML='<div class="result-panel finale suspense"><div class="eyebrow">FIVE SIGNINGS. ONE WINNER.</div><h2>WHO BUILT IT BETTER?</h2><div class="reveal-count" id="reveal-count" aria-hidden="true">3</div><p class="result-note" role="status">The squads are locked. Here comes the verdict.</p><button class="text-button" id="skip-reveal">Skip animation →</button></div>';
 if(scroll){$('results').scrollIntoView({behavior:reduced?'auto':'smooth',block:'center'});$('skip-reveal').focus?.({preventScroll:true});}
 $('skip-reveal').onclick=finish;
 if(reduced)finish();else{window.HBW_SOUND?.countdown();
  [2,1].forEach((n,i)=>revealTimers.push(setTimeout(()=>{if(run===epoch&&state.revealing){$('reveal-count').textContent=String(n);window.HBW_SOUND?.countdown();}},(i+1)*800)));
  revealTimers.push(setTimeout(finish,2400));
 }
 return result;
}
function readState(){return {firstBidder:state.firstBidder===null?null:state.firstBidder+1,mode:selectedMode,screen:$('home').hidden?'game':'home',poolSize:playerPool().length,phase:state.phase,auction:state.lot,basketballPlayer:state.current,bid:state.bid,leadingPlayer:state.leader===null?null:state.leader+1,turn:spotlight()===null?null:spotlight()+1,teams:state.teams.map((t,i)=>({player:i+1,budget:t.money,soloSkipsLeft:soloSkipsLeft(i),maxBid:maxBid(i),ready:!!t.ready,lineup:lineupFor(t)}))};}
function selectMode(mode){if(!['current','prime'].includes(mode))throw Error('Unknown mode.');selectedMode=mode;document.querySelectorAll('[data-mode]').forEach(el=>{el.classList.toggle('selected',el.dataset.mode===mode);el.setAttribute('aria-pressed',String(el.dataset.mode===mode));});$('start-game').textContent='Start '+modeNames[mode].toLowerCase()+' →';}
function showHome(){$('home').hidden=false;$('game').hidden=true;selectMode(selectedMode);window.scrollTo({top:0,behavior:'smooth'});}
function startGame(mode=selectedMode){if(!['current','prime'].includes(mode))throw Error('Choose current or prime.');reset(mode);window.HBW_SOUND?.start();$('home').hidden=true;$('game').hidden=false;window.scrollTo({top:0,behavior:'smooth'});return readState();}
document.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>{window.HBW_SOUND?.ui();selectMode(el.dataset.mode);});$('start-game').onclick=()=>startGame();
const ruleDialog=$('rules');$('rules-button').onclick=()=>{window.HBW_SOUND?.ui();ruleDialog.showModal();};document.querySelectorAll('#rules .close,#rules .close-rules').forEach(b=>b.onclick=()=>{window.HBW_SOUND?.ui();ruleDialog.close();});let leaveTarget='/';document.querySelectorAll('.brand-home,.brand-edition').forEach(link=>link.onclick=e=>{if($('home').hidden){e.preventDefault();leaveTarget=link.getAttribute('href');document.querySelector('.confirm-reset').textContent=leaveTarget==='/'?'Go to home':`Go to ${leaveTarget.includes('basketball')?'basketball':'football'}`;window.HBW_SOUND?.ui();$('restart').showModal();}});document.querySelector('.cancel-reset').onclick=()=>{$('restart').close();window.HBW_SOUND?.ui();};document.querySelector('.confirm-reset').onclick=()=>window.location.assign(leaveTarget);

function activateSlot(row){const t=Number(row.dataset.team),i=Number(row.dataset.slot);if(!canArrange(t))return;const order=state.teams[t].order||lineupFor(state.teams[t]).rows.map(r=>r?.player.id??null);
 if(selectedSlot?.team===t){const from=selectedSlot.slot;if(from===i){selectedSlot=null;renderTeams();return;}movePlayer(t,from,i);return;}
 if(order[i]!=null){selectedSlot={team:t,slot:i};renderTeams();}
}
function clearDrag(){
 dropRow?.classList.remove('drop-target');dropRow=null;
 if(dragState?.active){const {row,originalStyle}=dragState;row.classList.remove('dragging-player-tab');if(originalStyle===null)row.removeAttribute('style');else row.setAttribute('style',originalStyle);dragPlaceholder?.remove();document.body?.classList.remove('lineup-dragging');}
 dragPlaceholder=null;dragState=null;
}
function setupLineupInteractions(){if(!document.addEventListener)return;
 document.addEventListener('pointerdown',e=>{const row=e.target.closest?.('.roster-row.repositionable');if(!row||e.button!==0)return;const t=Number(row.dataset.team),i=Number(row.dataset.slot);if(!canArrange(t)||!lineupFor(state.teams[t]).rows[i])return;const rect=row.getBoundingClientRect();dragState={team:t,from:i,x:e.clientX,y:e.clientY,offsetX:e.clientX-rect.left,offsetY:e.clientY-rect.top,row,originalStyle:row.getAttribute('style'),active:false};});
 document.addEventListener('pointermove',e=>{if(!dragState)return;const d=dragState;if(!d.active&&Math.hypot(e.clientX-d.x,e.clientY-d.y)<8)return;
  if(!d.active){d.active=true;const rect=d.row.getBoundingClientRect();dragPlaceholder=document.createElement('div');dragPlaceholder.className='roster-row drag-placeholder';dragPlaceholder.style.height=`${rect.height}px`;dragPlaceholder.innerHTML=`<span class="slot-label">${slots[d.from]}</span><span class="roster-name">Move to a slot</span>`;d.row.before(dragPlaceholder);d.row.classList.add('dragging-player-tab');Object.assign(d.row.style,{position:'fixed',left:`${rect.left}px`,top:`${rect.top}px`,width:`${rect.width}px`,height:`${rect.height}px`,zIndex:'1000',pointerEvents:'none'});document.body.classList.add('lineup-dragging');selectedSlot=null;}
  e.preventDefault();d.row.style.left=`${e.clientX-d.offsetX}px`;d.row.style.top=`${e.clientY-d.offsetY}px`;
  const row=document.elementFromPoint(e.clientX,e.clientY)?.closest?.('.roster-row.repositionable');const next=row&&Number(row.dataset.team)===d.team&&Number(row.dataset.slot)!==d.from?row:null;if(dropRow!==next){dropRow?.classList.remove('drop-target');dropRow=next;dropRow?.classList.add('drop-target');}
 });
 document.addEventListener('pointerup',()=>{if(!dragState)return;const d=dragState,from=d.from,team=d.team,to=dropRow?Number(dropRow.dataset.slot):null,active=d.active;clearDrag();if(active){suppressRowClick=true;setTimeout(()=>suppressRowClick=false,0);if(to!==null&&canArrange(team))movePlayer(team,from,to);}});
 document.addEventListener('pointercancel',clearDrag);
 document.addEventListener('click',e=>{const row=e.target.closest?.('.roster-row.repositionable');if(!row||suppressRowClick)return;activateSlot(row);});
 document.addEventListener('keydown',e=>{if(!['Enter',' '].includes(e.key))return;const row=e.target.closest?.('.roster-row.repositionable');if(!row)return;e.preventDefault();activateSlot(row);});
}

setupLineupInteractions();
reset();
showHome();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const definitions=[{name:'toss_first_bidder',description:'Flip a fair coin to decide who opens the first auction. Waits for the result.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>toss()},{name:'start_basketball_game',description:'Start a fresh game in current or prime mode, clearing previous signings.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['current','prime']}},required:['mode'],additionalProperties:false},execute:input=>startGame(input?.mode)},{name:'read_basketball_auction',description:'Read current auction, budgets and chosen lineups.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>readState(),readOnly:true},{name:'spin_basketball_player',description:'Spin and reveal the next basketball player before a new auction. Waits for the reveal.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>spin()},{name:'place_basketball_bid',description:'Bid for the player whose turn it is. Default raises by $1; amount can go up to their full balance. At zero budget, wait until paid bidding ends, then spin each free signing separately.',inputSchema:{type:'object',properties:{player:{type:'integer',enum:[1,2]},amount:{type:'integer',minimum:1,maximum:20}},required:['player'],additionalProperties:false},execute:input=>{if(!input||![1,2].includes(input.player))throw Error('Player must be 1 or 2.');return bid(input.player-1,input.amount);}},{name:'pass_basketball_bid',description:'Pass freely while both managers can buy. When the rival has no budget or a full squad, only three solo skips are allowed per match. If there is a leading bidder, complete their signing.',inputSchema:{type:'object',properties:{player:{type:'integer',enum:[1,2]}},required:['player'],additionalProperties:false},execute:input=>{if(!input||![1,2].includes(input.player))throw Error('Player must be 1 or 2.');return pass(input.player-1);}}];for(const d of definitions){try{Promise.resolve(document.modelContext.registerTool({name:d.name,description:d.description,inputSchema:d.inputSchema,execute:d.execute,annotations:{readOnlyHint:!!d.readOnly,untrustedContentHint:false}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
